import {equipmentArt} from './equipment-art.js';
import {concentration,point,active,leadPoint} from './measurement-common.js';
const outline='stroke="#253e59" stroke-width="2" stroke-linejoin="miter"';
const numbers={0:'abcdef',1:'bc',2:'abdeg',3:'abcdg',4:'bcfg',5:'acdfg',6:'acdefg',7:'abc',8:'abcdefg',9:'abcdfg','-':'g'};
const strokes={a:[1,0,5,0],b:[6,1,6,5],c:[6,7,6,11],d:[1,12,5,12],e:[0,7,0,11],f:[0,1,0,5],g:[1,6,5,6]};
export function lcd(value,unit,x,y,w=120){let dx=0,art='';for(const c of value){if(c==='.'){art+=`<rect x="${dx}" y="11" width="1.5" height="1.5"/>`;dx+=3;}else{art+=`<g transform="translate(${dx} 0)">${Object.entries(strokes).map(([k,p])=>`<path d="M${p[0]} ${p[1]}L${p[2]} ${p[3]}" stroke="#173f39" stroke-width="1.5" opacity="${(numbers[c]||'').includes(k)?1:.08}"/>`).join('')}</g>`;dx+=10;}}
 return `<g role="img" aria-label="${value} ${unit}"><rect x="${x}" y="${y}" width="${w}" height="29" rx="2" fill="#1c3e50" stroke="#b3cac5"/><rect x="${x+3}" y="${y+3}" width="${w-6}" height="23" fill="#89b6a0"/><g transform="translate(${x+10} ${y+6}) scale(1.35)" fill="#173f39">${art}</g><text x="${x+w-9}" y="${y+20}" font-family="monospace" font-size="9" text-anchor="end" fill="#173f39">${unit}</text></g>`;
}
const selection=(w,h,top=-20)=>`<rect class="select-outline" x="${-w/2-8}" y="${top}" width="${w+16}" height="${h-top+8}"/>`;
function vessel(o,s){const h=o.kind==='cuvette'?60:96,w=o.kind==='cuvette'?27:78,cu=concentration(o,'Cu'),blue=cu>0?`rgb(${Math.round(155-80*Math.min(1,cu/.1))},${Math.round(215-60*Math.min(1,cu/.1))},223)`:'#99cbd3',salt=(o.solidNaCl||0)*58.44;
 if(o.kind==='cuvette'){const level=56-45*Math.min(1,o.water/o.capacity),id='cuvette-'+o.id;return `<defs><clipPath id="${id}"><rect x="-10" y="4" width="20" height="51"/></clipPath></defs><path d="M-13 0V56H13V0" fill="#d8eff080" ${outline}/><g clip-path="url(#${id})">${o.water>0?`<rect x="-10" y="${level}" width="20" height="${56-level}" fill="${blue}" opacity=".8"/>`:''}</g><path d="M-8 5V51" stroke="#f6ffec" stroke-width="2"/>${o.clearFace?'':'<path d="M-10 12L10 32M-10 22L10 42M-10 32L10 52" stroke="#a4b8bc" stroke-width="2"/>'}${o.clean?'':'<path d="M-5 25q10-6 10 7M-6 29q9-5 9 5" fill="none" stroke="#af9878" opacity=".7"/>'}<text y="-9" text-anchor="middle" font-size="9">${o.id==='cuvetteA'?'A':'B'}</text>${selection(w,h)}`;}
 const level=86-72*Math.min(1,o.water/o.capacity),html=`<g clip-path="url(#unused)"><rect x="-35" y="${level}" width="70" height="${96-level}" fill="${blue}"/></g><text y="-40" text-anchor="middle" font-size="9">${o.name}</text>${selection(w,h)}`;
 return equipmentArt({...o,salt,dissolved:0},html,'measurement',s);
}
export function art(o,s,r){
 if(o.kind==='beaker'||o.kind==='cuvette')return vessel(o,s);
 if(o.kind==='electrode'||o.kind==='metalStrip'){const metal=o.metal==='Zn'?'#a5b2ba':o.metal==='Cu'?'#bd7b4c':'#4c6166',w=o.kind==='electrode'?8:18,rim=o.parent?((o.offset?.x||0)<0||o.metal==='Zn'?-39:39)-(o.offset?.x||0):0;return `${o.parent?`<path d="M0 4V12H${rim}V22" fill="none" stroke="#405d70" stroke-width="5"/><path d="M0 10H${rim}" stroke="#b4cbd0" stroke-width="2"/>`:''}<path d="M${-w/2} 0H${w/2}V90H${-w/2}Z" fill="${metal}" ${outline}/><path d="M${-w/2+2} 5V84" stroke="#deebdf" stroke-width="2" opacity=".6"/>${o.plated>0?`<path d="M${-w/2+1} 60V87H${w/2-1}V60" fill="#ce9460" opacity=".7"/>`:''}<rect x="-9" y="-6" width="18" height="13" fill="#2d495b" ${outline}/><circle class="electrical-terminal" data-terminal="${o.id}" r="6" fill="${o.metal==='Cu'?'#be6b4c':'#d4dbc6'}" ${outline}/><text y="-15" text-anchor="middle" font-size="10">${o.metal|| (o.id==='electrodeA'?'A':'B')}</text>${selection(24,90,-26)}`;}
 if(o.kind==='saltBridge')return `<path d="M-94 80V20Q-94 5-78 5H78Q94 5 94 20V80" fill="none" stroke="#27465d" stroke-width="14"/><path d="M-94 80V20Q-94 5-78 5H78Q94 5 94 20V80" fill="none" stroke="#b0d7c3" stroke-width="9"/><path d="M-96 78V20Q-96 3-78 3H78" fill="none" stroke="#ecf4dd" stroke-width="2"/><text y="-9" text-anchor="middle" font-size="10">KNO₃ gel</text>${selection(210,85)}`;
 if(o.kind==='colorimeter'){const value=r.value===null?'----':r.value.toFixed(3);return `<path d="M-92 0H80L92 12V84H-92Z" fill="#658897" ${outline}/><path d="M-92 0H80L92 12H-80Z" fill="#abc5c8" ${outline}/><rect x="24" y="3" width="51" height="72" fill="#263e50" ${outline}/><path d="M24 15H75" stroke="${o.lid?'#8fa4a5':'#ebc36a'}" stroke-width="8"/>${o.lid?'<path d="M21 2H78V12H21Z" fill="#516d80" stroke="#263e50" stroke-width="2"/>':''}<text x="-82" y="27" fill="#e3efdb" font-size="9">ABSORBANCE</text>${lcd(value,'A',-83,34,100)}<rect x="-80" y="73" width="12" height="6" fill="#b1d3c1"/><rect x="-59" y="73" width="12" height="6" fill="#b1d3c1"/><text x="-35" y="86" font-size="9" fill="#e5f0df">${s.filter.toUpperCase()}</text>${selection(185,90)}`;}
 const value=s.mode==='voltaic'?r.voltage:r.value,unit=s.mode==='voltaic'?'V':'mS';return `<path d="M-72 0H60L72 12V76H-72Z" fill="#547b8d" ${outline}/><path d="M-72 0H60L72 12H-60Z" fill="#abc3c7" ${outline}/><text y="16" text-anchor="middle" font-size="8" fill="#e3efdb">${s.mode==='voltaic'?'CELL METER':'CONDUCTANCE'}</text>${lcd(value===null?'----':value.toFixed(s.mode==='voltaic'||value>=1?3:5),unit,-63,22,126)}<rect x="-50" y="61" width="14" height="7" fill="#c2d4ba"/><circle cx="49" cy="65" r="7" fill="#263f52" stroke="#a6c1c0"/><circle cx="-45" cy="0" r="6" fill="#b25948" ${outline}/><circle cx="45" cy="0" r="6" fill="#293848" ${outline}/>${selection(145,80)}`;
}
export function wires(s,layer='all'){if(s.mode==='colorimetry'||!active(s.items.meter))return'';const m=s.items.meter;return ['red','black'].map(c=>{const p=point(m,c==='red'?-45:45,0),q=leadPoint(s,c),colour=c==='red'?'#a95147':'#344553';const cable=`<path d="M${p.x} ${p.y}C${p.x} ${p.y-70},${q.x} ${q.y-50},${q.x} ${q.y}" fill="none" stroke="${colour}" stroke-width="4"/>`,end=`<circle class="lead-end" data-lead="${c}" cx="${q.x}" cy="${q.y}" r="9" fill="${colour}" stroke="#d3dfc7" stroke-width="2" aria-hidden="true"/>`;return layer==='cables'?cable:layer==='ends'?end:cable+end;}).join('');}
